"""Remaining beach records. Imported at the end of beaches.py so add() already exists."""
from beaches import add, fsp, FEE, NOFILL, NOCHAIR, NOMAT, NOSHELL, PIN_FAQ, PIN_DOG, PIN_LIFE, MAN_LIFE

FSP_DOG_NO = "The park page says pets are not allowed on the beach. Service animals are described separately on the page."
FSP_GUARD_NO = "The park page says lifeguards are not provided. Swim at your own risk and read the flag sign."
FSP_CHAIR = "The park page says a beach wheelchair is available at no charge. Ask at the place the page names. We do not print a phone number."

def park(slug, name, short, region, county, county_name, place, water, **k):
    k.setdefault("manager", "Florida State Parks")
    k.setdefault("kids", False)
    k.setdefault("sunset", False)
    k.setdefault("free_access", False)
    k.setdefault("extra", [])
    add(slug=slug, name=name, short=short, region=region, county=county, county_name=county_name,
        place=place, water=water, **k)

